/**
 * Can every effect say which turn caused it? — `npm run check:provenance`.
 *
 * ## Why this exists
 *
 * `app.my_task_add` has taken `p_job` since it existed and the handler never
 * passed it. Three things depend on that link — ADR-0041's boundary
 * `app.harness_task`, the reversal `app.undo_tasks_from_job`, and
 * `check:leaks` — and all three were blind, so thirty tasks generated by
 * simulated messages sat on Grant's personal list reading `added_by =
 * 'grant'` while every witness reported it clean.
 *
 * One argument fixed that one caller. This asks the general question, because
 * a class fixed at one site is a class that comes back at the next.
 *
 * ## The measure is NOT "how many rows are null"
 *
 * That number is alarming and mostly wrong, and running it first would have
 * sent somebody fixing four things that are not broken:
 *
 *   - `undoable_actions` is 280 of 280 without a job — and its
 *     `correlation_id` is NOT NULL and present on every row, and not one of
 *     those correlations matches a job. They are things Grant did on the
 *     dashboard. There is no job to record.
 *   - `blockers` is 392 without a job and NONE in the last two days, so the
 *     gap is historical and already closed.
 *   - `lessons` is dominated by `verify:lessons`, and a lesson taught through
 *     the dashboard legitimately has no job either.
 *
 * So the question is not "is it null" but **"could this row have named a job,
 * and did it"**. A row is counted only when something else about it proves a
 * job existed: a correlation that matches one, or an author that is an agent
 * rather than a person. Everything else is absence, not a gap, and 0304's
 * asymmetry applies — the absence of a link is not the presence of a defect.
 */

import '../src/safety/require-production-checks.ts'
import { ManagementApiExecutor } from '../src/db/executor.ts'

const token = process.env.SUPABASE_ACCESS_TOKEN
if (token === undefined || token === '') {
  console.log('\n  SUPABASE_ACCESS_TOKEN is not set; provenance lives in the database.\n')
  process.exit(0)
}

const db = new ManagementApiExecutor(
  process.env.SUPABASE_PROJECT_REF ?? 'baujwlzcziasnfhhkchg',
  token,
)

interface Gap {
  readonly table: string
  readonly column: string
  readonly total: number
  readonly unattributed: number
  /** Of those, the ones something else proves came from a job. */
  readonly gap: number
  /** Of THOSE, ones written in the last day: a wound rather than a scar. */
  readonly recent: number
  readonly why: string
}

/*
  Each entry names its own evidence that a job existed. Written per table
  rather than generically, because what proves a job differs: a correlation
  that matches one, or an author who is a member of staff and therefore
  cannot have used the dashboard as Grant.
*/
const QUERIES: readonly { table: string; column: string; sql: string; why: string }[] = [
  {
    table: 'tasks',
    column: 'job_id',
    why: 'a task whose correlation-mate is a job, or whose author is an agent',
    sql: `select count(*)::int total,
                 count(*) filter (where t.job_id is null)::int unattributed,
                 count(*) filter (where t.job_id is null
                   and exists (select 1 from public.staff s where s.slug = t.added_by))::int gap,
                 count(*) filter (where t.job_id is null
                   and exists (select 1 from public.staff s where s.slug = t.added_by)
                   and t.created_at > now() - interval '24 hours')::int recent
            from public.tasks t`,
  },
  {
    table: 'documents',
    column: 'produced_by_job',
    why: 'a document the office MADE (origin = made) must name the turn that made it',
    sql: `select count(*)::int total,
                 count(*) filter (where d.produced_by_job is null)::int unattributed,
                 count(*) filter (where d.produced_by_job is null and d.origin = 'made')::int gap,
                 count(*) filter (where d.produced_by_job is null and d.origin = 'made'
                   and d.created_at > now() - interval '24 hours')::int recent
            from public.documents d`,
  },
  {
    table: 'blockers',
    column: 'job_id',
    why: 'a blocker is raised BY a turn; one without a job cannot be answered back into it',
    sql: `select count(*)::int total,
                 count(*) filter (where b.job_id is null)::int unattributed,
                 count(*) filter (where b.job_id is null
                   and b.created_at > now() - interval '7 days')::int gap,
                 count(*) filter (where b.job_id is null
                   and b.created_at > now() - interval '24 hours')::int recent
            from public.blockers b`,
  },
  {
    table: 'lessons',
    column: 'from_job',
    why: 'a lesson whose author is a member of staff came from a turn',
    sql: `select count(*)::int total,
                 count(*) filter (where l.from_job is null)::int unattributed,
                 count(*) filter (where l.from_job is null
                   and exists (select 1 from public.staff s where s.slug = l.learned_by))::int gap,
                 count(*) filter (where l.from_job is null
                   and exists (select 1 from public.staff s where s.slug = l.learned_by)
                   and l.created_at > now() - interval '24 hours')::int recent
            from public.lessons l`,
  },
  {
    table: 'skills',
    column: 'from_job',
    why: 'a skill whose author is a member of staff came from a turn',
    sql: `select count(*)::int total,
                 count(*) filter (where k.from_job is null)::int unattributed,
                 count(*) filter (where k.from_job is null
                   and exists (select 1 from public.staff s where s.slug = k.authored_by))::int gap,
                 count(*) filter (where k.from_job is null
                   and exists (select 1 from public.staff s where s.slug = k.authored_by)
                   and k.created_at > now() - interval '24 hours')::int recent
            from public.skills k`,
  },
  {
    table: 'undoable_actions',
    column: 'job_id',
    why: 'an action whose correlation matches a job could have named it',
    sql: `select count(*)::int total,
                 count(*) filter (where u.job_id is null)::int unattributed,
                 count(*) filter (where u.job_id is null
                   and exists (select 1 from public.jobs j
                                where j.correlation_id = u.correlation_id))::int gap,
                 count(*) filter (where u.job_id is null
                   and exists (select 1 from public.jobs j
                                where j.correlation_id = u.correlation_id)
                   and u.performed_at > now() - interval '24 hours')::int recent
            from public.undoable_actions u`,
  },
  {
    table: 'deliveries',
    column: 'job_id',
    why: 'a delivery whose correlation matches a job could have named it',
    sql: `select count(*)::int total,
                 count(*) filter (where d.job_id is null)::int unattributed,
                 count(*) filter (where d.job_id is null
                   and exists (select 1 from public.jobs j
                                where j.correlation_id = d.correlation_id))::int gap,
                 count(*) filter (where d.job_id is null
                   and exists (select 1 from public.jobs j
                                where j.correlation_id = d.correlation_id)
                   and d.created_at > now() - interval '24 hours')::int recent
            from public.deliveries d`,
  },
]

const found: Gap[] = []
for (const q of QUERIES) {
  try {
    const row = (await db.execute(q.sql)).rows[0] as Record<string, unknown>
    found.push({
      table: q.table,
      column: q.column,
      total: Number(row.total ?? 0),
      unattributed: Number(row.unattributed ?? 0),
      gap: Number(row.gap ?? 0),
      recent: Number(row.recent ?? 0),
      why: q.why,
    })
  } catch (error) {
    console.log(
      `  ${q.table}: could not be asked — ${String((error as Error).message).slice(0, 90)}`,
    )
  }
}

console.log('\ncheck:provenance — can every effect name the turn that caused it?\n')
console.log(
  `  ${'table'.padEnd(18)}${'rows'.padStart(7)}${'no link'.padStart(10)}${'gap'.padStart(6)}${'LAST DAY'.padStart(10)}`,
)
for (const f of found)
  console.log(
    `  ${f.table.padEnd(18)}${String(f.total).padStart(7)}${String(f.unattributed).padStart(10)}${String(f.gap).padStart(6)}${String(f.recent).padStart(10)}`,
  )

/*
  A gap with nothing recent in it is a SCAR, not a wound.

  Every gap this found on its first run was historical - zero in the last
  day - because the paths were fixed and the old rows stay. Failing on
  those would make the check red for ever over something nobody can
  change, and CLAUDE.md is unambiguous that a check which cries wolf is
  one somebody starts overriding.
*/
const real = found.filter((f) => f.recent > 0)
const healed = found.filter((f) => f.gap > 0 && f.recent === 0)
console.log(
  '\n  "no link" is not a defect: a document Grant uploaded, a task he typed and',
  '\n  an action he took on the dashboard all legitimately have no job. GAP counts',
  '\n  only rows where something ELSE proves a turn existed.\n',
)

if (healed.length > 0) {
  console.log('  HISTORICAL, and not counted: the path is fixed and the old rows remain.')
  for (const f of healed) console.log(`    ${f.table}.${f.column}: ${String(f.gap)}`)
  console.log()
}

if (real.length === 0) {
  console.log('  No provenance gap written in the last day. Every effect a turn')
  console.log('  caused in that window names the turn that caused it.\n')
  process.exit(0)
}

for (const f of real)
  console.log(`  GAP  ${f.table}.${f.column}: ${String(f.recent)} in the last day — ${f.why}`)
console.log()
process.exit(1)
